"""Print the next order id to stdout.

Reads ids.txt from the current directory (one order id per line, most recent last)
and prints the next sequential id. Ids have the form ORD- followed by four base36
characters (digits 0-9, letters A-Z).
"""

from __future__ import annotations

import sys
from pathlib import Path


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded base-36 string of the given width."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result: list[str] = []
    for _ in range(width):
        result.append(chars[n % 36])
        n //= 36
    return "".join(reversed(result))


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    return int(s, 36)


def next_id(current: str) -> str:
    """Given an id like 'ORD-243G', return the next one like 'ORD-243H'."""
    if not current.startswith("ORD-") or len(current) != 8:
        raise ValueError(f"unexpected id format: {current!r}")
    suffix = current[4:]
    n = base36_decode(suffix)
    n += 1
    return "ORD-" + base36_encode(n, width=4)


def main() -> None:
    ids_path = Path("ids.txt")
    if not ids_path.exists():
        print("error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    lines = ids_path.read_text(encoding="utf-8").strip().splitlines()
    if not lines:
        print("error: ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    last_id = lines[-1].strip()
    print(next_id(last_id))


if __name__ == "__main__":
    main()

