#!/usr/bin/env python3
"""Generate the next order id."""

import sys

ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
BASE = len(ALPHABET)  # 32


def decode(s: str) -> int:
    """Convert a base-32 code string to an integer."""
    v = 0
    for c in s:
        v = v * BASE + ALPHABET.index(c)
    return v


def encode(v: int) -> str:
    """Convert an integer to a 4-character base-32 code string."""
    chars = []
    for _ in range(4):
        chars.append(ALPHABET[v % BASE])
        v //= BASE
    return "".join(reversed(chars))


def main() -> None:
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        # No ids yet; start at zero.
        next_code = encode(0)
    else:
        last_line = lines[-1]
        last_code = last_line.split("-", 1)[1]
        last_val = decode(last_code)
        next_code = encode(last_val + 1)

    print(f"ORD-{next_code}")


if __name__ == "__main__":
    main()

