"""Read ids.txt and print the next sequential order id to stdout."""

from __future__ import annotations

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int) -> str:
    """Convert a non-negative integer to a zero-padded 4-character base-36 string."""
    chars: list[str] = []
    for _ in range(4):
        n, r = divmod(n, 36)
        chars.append(BASE36[r])
    return "".join(reversed(chars))


def from_base36(s: str) -> int:
    """Convert a base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch)
    return n


def main() -> None:
    try:
        with open("ids.txt", encoding="utf-8") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("error: ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    last_id = lines[-1]

    if not last_id.startswith("ORD-") or len(last_id) != 8:
        print(f"error: unexpected id format: {last_id!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    try:
        n = from_base36(suffix)
    except ValueError:
        print(f"error: invalid base-36 suffix: {suffix!r}", file=sys.stderr)
        sys.exit(1)

    next_suffix = to_base36(n + 1)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

