    """Return a casefolded, accent-insensitive sort key."""
    # Decompose into base characters + combining marks
    decomposed = unicodedata.normalize("NFD", name.strip())
    # Strip combining diacritical marks (accents)
    no_accents = "".join(ch for ch in decomposed if unicodedata.category(ch) != "Mn")
