"""Deduplicate events.jsonl by event_id, keeping first occurrence."""

import json
import sys
from pathlib import Path


def main() -> None:
    input_path = Path("events.jsonl")
    output_path = Path("deduped.jsonl")

    if not input_path.is_file():
        print(f"Error: {input_path} not found", file=sys.stderr)
        sys.exit(1)

    seen: set[str] = set()
    output_lines: list[str] = []

    with input_path.open("r") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
