#!/usr/bin/env python3
"""Deduplicate events.jsonl by event_id, keeping first occurrence."""

import json
import sys
from pathlib import Path


def main() -> None:
    input_path = Path("events.jsonl")
    output_path = Path("deduped.jsonl")

    if not input_path.is_file():
        print(f"Error: {input_path} not found", file=sys.stderr)
        sys.exit(1)

    seen: set[str] = set()
    output_lines: list[str] = []

    with input_path.open("r") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError as e:
                print(f"Error: invalid JSON: {e}", file=sys.stderr)
                sys.exit(1)

            event_id = obj.get("event_id")
            if event_id is None:
                print("Error: missing event_id", file=sys.stderr)
                sys.exit(1)

            if event_id not in seen:
                seen.add(event_id)
                output_lines.append(line)

    with output_path.open("w") as f:
        for line in output_lines:
            f.write(line + "\n")

    print(f"Wrote {len(output_lines)} events to {output_path}")


if __name__ == "__main__":
    main()

