#!/usr/bin/env python3
"""Count word occurrences in all .txt files under docs/."""

import os
from collections import Counter
from pathlib import Path

PUNCTUATION = ".,;:!?"


def strip_punctuation(word: str) -> str:
    """Strip punctuation characters from the edges of a word."""
    return word.strip(PUNCTUATION)


def main() -> None:
    counter: Counter[str] = Counter()
    docs_dir = Path("docs")

    for txt_path in sorted(docs_dir.rglob("*.txt")):
        text = txt_path.read_text(encoding="utf-8")
        for raw_word in text.split():
            word = strip_punctuation(raw_word).lower()
            if word:  # skip empty strings (e.g. if word was pure punctuation)
                counter[word] += 1

    lines = [f"{word} {count}\n" for word, count in sorted(counter.items())]
    Path("counts.txt").write_text("".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()

