#!/usr/bin/env python3
"""Rotate entries from app.log into archive.log based on age."""

import sys
import os
from datetime import datetime, timedelta, timezone

LOG_DIR = os.path.dirname(os.path.abspath(__file__))
APP_LOG = os.path.join(LOG_DIR, "app.log")
ARCHIVE_LOG = os.path.join(LOG_DIR, "archive.log")


def parse_ts(line: str) -> datetime | None:
    """Parse leading YYYY-MM-DD HH:MM:SS from a log line as UTC."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    if not os.path.exists(APP_LOG):
        return

    with open(APP_LOG, "r") as f:
        lines = f.readlines()

    keep = []
    archive = []

    for line in lines:
        ts = parse_ts(line)
        if ts is None:
            # Lines without a parseable timestamp stay in app.log
            keep.append(line)
        elif ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    if archive:
        with open(ARCHIVE_LOG, "a") as f:
            f.writelines(archive)

    with open(APP_LOG, "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

